 static Mesh FlameMesh(){string path=Root+"/Meshes/Flame.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old)return old;var mesh=new Mesh{name="Authored tapered flame"};var v=new List<Vector3>();var t=new List<int>();const int n=12,layers=9;for(int j=0;j<layers;j++){float y=j/(float)(layers-1);float radius=Mathf.Sin(Mathf.PI*Mathf.Pow(y,.7f))*.34f+.005f;for(int i=0;i<n;i++){float a=i*2*Mathf.PI/n;v.Add(new Vector3(Mathf.Cos(a)*radius+Mathf.Sin(y*5)*y*.2f,y,Mathf.Sin(a)*radius*.6f));}}for(int j=0;j<layers-1;j++)for(int i=0;i<n;i++){int a=j*n+i,b=j*n+(i+1)%n;t.AddRange(new[]{a,b,a+n,b,b+n,a+n});}mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static void Flames(){for(int i=0;i<7;i++){var g=new GameObject("Flame tongue "+i);g.transform.position=new Vector3((i%4-1.5f)*.22f,.27f,(i/4-.5f)*.22f);g.transform.localScale=new Vector3(1, .75f+(i%3)*.23f,1);g.AddComponent<MeshFilter>().sharedMesh=FlameMesh();g.AddComponent<MeshRenderer>().sharedMaterial=Mat("Fire"+i,i%2==0?new Color(1,.28f,.015f):new Color(1,.73f,.08f));}}

 static Mesh LeafMesh(){string p=Root+"/Meshes/Leaf.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(old)return old;var m=new Mesh{name="Authored leaf silhouette"};Vector3[] rim={new Vector3(0,0,.42f),new Vector3(.12f,0,.18f),new Vector3(.26f,0,.23f),new Vector3(.19f,0,.05f),new Vector3(.32f,0,-.04f),new Vector3(.16f,0,-.12f),new Vector3(.1f,0,-.27f),new Vector3(0,0,-.18f),new Vector3(-.1f,0,-.27f),new Vector3(-.16f,0,-.12f),new Vector3(-.32f,0,-.04f),new Vector3(-.19f,0,.05f),new Vector3(-.26f,0,.23f),new Vector3(-.12f,0,.18f)};m.vertices=new[]{Vector3.zero}.Concat(rim).ToArray();var tris=new List<int>();for(int i=0;i<rim.Length;i++){int a=i+1,b=(i+1)%rim.Length+1;tris.AddRange(new[]{0,a,b,0,b,a});}m.triangles=tris.ToArray();m.RecalculateNormals();AssetDatabase.CreateAsset(m,p);return m;}
 static void Ghost(){Floor(0);var stone=Mat("Stone",new Color(.32f,.34f,.35f));for(int i=0;i<10;i++){float a=i*Mathf.PI*.2f;Part("Fire stone",PrimitiveType.Sphere,new Vector3(Mathf.Cos(a)*.85f,.15f,Mathf.Sin(a)*.85f),new Vector3(.4f,.27f,.32f),stone);}for(int i=0;i<3;i++){var g=Part("Firewood",PrimitiveType.Cylinder,new Vector3(0,.22f,0),new Vector3(.22f,.7f,.22f),Mat("Wood",new Color(.30f,.17f,.08f)));g.transform.rotation=Quaternion.Euler(80,60*i,0);}Flames();
 demo.windGuides=new GameObject("Updraft — explanatory vector guides");for(int i=-1;i<=1;i++){Vector3 a=new Vector3(i*.65f,.8f,.3f),b=a+Vector3.up*2.3f;Line("Upward wind",new[]{a,b,b+new Vector3(-.16f,-.24f,0),b,b+new Vector3(.16f,-.24f,0)},teal,.045f,demo.windGuides.transform);}
 demo.leaves=new Transform[24];demo.leafSeeds=new Vector3[24];for(int i=0;i<24;i++){var g=new GameObject("Leaf particle "+i);g.AddComponent<MeshFilter>().sharedMesh=LeafMesh();g.AddComponent<MeshRenderer>().sharedMaterial=Mat("Leaf"+(i%3),i%3==0?yellow:i%3==1?new Color(.86f,.38f,.12f):new Color(.65f,.68f,.12f));g.transform.localScale=Vector3.one*.64f;demo.leaves[i]=g.transform;demo.leafSeeds[i]=new Vector3(-3-(i%4)*.4f,2+(i/4)*.13f,(i%3-1)*.45f);}}
 static Transform Mannequin(float x,Color c){var root=new GameObject("Articulated animation test subject").transform;root.position=new Vector3(x,0,0);Material suit=Mat("Suit"+x,c),skin=Mat("Mannequin",white),joint=Mat("Joint",new Color(.18f,.21f,.23f));
