 for(int side=-1;side<=1;side+=2){part("Thigh",PrimitiveType.Capsule,new Vector3(side*.16f,.69f,0),new Vector3(.21f,.27f,.24f),skin);part("Knee",PrimitiveType.Sphere,new Vector3(side*.16f,.47f,0),Vector3.one*.22f,joint);part("Shin",PrimitiveType.Capsule,new Vector3(side*.16f,.27f,0),new Vector3(.17f,.22f,.20f),skin);part("Boot",PrimitiveType.Cube,new Vector3(side*.16f,.06f,-.11f),new Vector3(.23f,.13f,.4f),joint);}
 var pivot=new GameObject("Measured shoulder rotation").transform;pivot.SetParent(root);pivot.localPosition=new Vector3(.39f,1.57f,0);Part("Shoulder joint",PrimitiveType.Sphere,pivot.position,Vector3.one*.24f,joint,pivot);Part("Upper arm",PrimitiveType.Capsule,pivot.position+Vector3.down*.20f,new Vector3(.18f,.23f,.18f),skin,pivot);Part("Elbow",PrimitiveType.Sphere,pivot.position+Vector3.down*.42f,Vector3.one*.19f,joint,pivot);Part("Forearm",PrimitiveType.Capsule,pivot.position+Vector3.down*.61f,new Vector3(.16f,.20f,.16f),skin,pivot);Part("Hand",PrimitiveType.Capsule,pivot.position+Vector3.down*.83f,new Vector3(.16f,.12f,.12f),skin,pivot);Part("Thumb",PrimitiveType.Capsule,pivot.position+new Vector3(-.09f,-.80f,0),new Vector3(.07f,.07f,.07f),skin,pivot);
 part("Other arm",PrimitiveType.Capsule,new Vector3(-.39f,1.2f,0),new Vector3(.18f,.4f,.18f),skin);return pivot;}
 static void Gears(){Floor(0);demo.armA=Mannequin(-1.4f,red);demo.armB=Mannequin(1.4f,teal);}
 static void Portal(){Floor(0);var wall=Mat("PortalWall",new Color(.20f,.25f,.27f));Part("Left wall",PrimitiveType.Cube,new Vector3(-3,2,0),new Vector3(.2f,4,8),wall);Part("Right wall",PrimitiveType.Cube,new Vector3(3,2,0),new Vector3(.2f,4,8),wall);
 for(int i=0;i<6;i++)Part("Floor path marker",PrimitiveType.Cube,new Vector3(.8f,.03f,-3+i),new Vector3(.15f,.03f,.5f),Mat("Path",teal));Part("Room landmark",PrimitiveType.Sphere,new Vector3(-1.8f,.5f,1),Vector3.one*.7f,Mat("Landmark",yellow));
 var q=GameObject.CreatePrimitive(PrimitiveType.Quad);q.name="Actual stencil-masked portal surface";q.transform.position=new Vector3(0,1.8f,3.8f);q.transform.localScale=new Vector3(2.4f,3.5f,1);demo.portalSurface=q.transform;Object.DestroyImmediate(q.GetComponent<Collider>());var m=new Material(Shader.Find("Yamyam/DistinctivePortalStencil"));var p=Root+"/Materials/Portal.mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,p);q.GetComponent<Renderer>().sharedMaterial=m;demo.portalMaterial=m;
 var ps=new List<Vector3>();for(int i=0;i<=80;i++){float a=i*Mathf.PI*2/80;ps.Add(new Vector3(Mathf.Cos(a)*1.22f,1.8f+Mathf.Sin(a)*1.77f,3.77f));}Line("Portal boundary",ps.ToArray(),yellow,.08f);
 recursive=new GameObject("Recursive transformed-view camera").AddComponent<Camera>();recursive.enabled=false;portalRT=new RenderTexture[4];for(int i=0;i<4;i++){portalRT[i]=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32);portalRT[i].Create();}}
 static void Build(){foreach(var s in new[]{"Scenes","Meshes","Materials"})Directory.CreateDirectory(Root+"/"+s);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;PlayerSettings.colorSpace=ColorSpace.Linear;QualitySettings.antiAliasing=1;
 demo=new GameObject("Editable teaching controls").AddComponent<DemoState>();demo.topic=job.topic;cam=new GameObject("Observer camera").AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.nearClipPlane=.03f;cam.farClipPlane=100;cam.aspect=1;cam.allowHDR=false;player=new GameObject("Player camera").AddComponent<Camera>();player.enabled=false;player.clearFlags=CameraClearFlags.SolidColor;player.backgroundColor=Color.black;player.aspect=1;player.nearClipPlane=.03f;player.farClipPlane=100;demo.observer=cam;demo.player=player;player.cullingMask=~(1<<8);
 lineMat=new Material(Shader.Find("Sprites/Default"));string lp=Root+"/Materials/Lines.mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(lp);if(existing){Object.DestroyImmediate(lineMat);lineMat=existing;}else AssetDatabase.CreateAsset(lineMat,lp);
 if(job.topic=="titanfall")Titan();else if(job.topic=="superliminal")Perspective();else if(job.topic=="ghost")Ghost();else if(job.topic=="gears")Gears();else Portal();
 Directory.CreateDirectory(Root+"/Scenes/"+job.topic);foreach(var s in job.sections.Where(x=>!x.StartsWith("game")).Distinct()){demo.section=s;demo.elapsed=2.8f;demo.Apply();cam.enabled=true;EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Root+"/Scenes/"+job.topic+"/"+s+".unity");cam.enabled=false;}AssetDatabase.SaveAssets();
 rt=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32);rt.Create();playerRT=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32);playerRT.Create();cam.targetTexture=rt;player.targetTexture=playerRT;image=new Texture2D(W,H,TextureFormat.RGB24,false);
 }
 static Vector3 Screen(Vector3 p){var v=cam.WorldToScreenPoint(p);return new Vector3(v.x,H-v.y,v.z);}
 static Record State(int f,string s,float e){demo.section=s;demo.elapsed=e;demo.Apply();return new Record{frame=f,section=s,elapsed=e,height=demo.actor?demo.actor.position.y:0,distance=demo.distance,scale=demo.scale,angle=demo.angle,offset=demo.offset,velocity=demo.velocity,depth=demo.depth,views=job.topic=="portal"?demo.depth+1:1,focus=Screen(demo.actor?demo.actor.position+Vector3.up:demo.pawn?demo.pawn.position:demo.armB?demo.armB.position:new Vector3(0,1.5f,0)),secondary=Screen(new Vector3(0,1.5f,6)),origin=Screen(player.transform.position),shoulderA=Screen(demo.armA?demo.armA.position:Vector3.zero),handA=Screen(demo.armA?demo.armA.TransformPoint(Vector3.down*.83f):Vector3.zero),handB=Screen(demo.armB?demo.armB.TransformPoint(Vector3.down*.83f):Vector3.zero)};}
 static void RenderPortal(){demo.portalMaterial.mainTexture=Texture2D.blackTexture;for(int i=demo.depth;i>=1;i--){recursive.CopyFrom(cam);recursive.enabled=false;recursive.targetTexture=portalRT[i];recursive.transform.position=cam.transform.position+Vector3.back*7.6f*i;recursive.transform.rotation=cam.transform.rotation;
 var mat=recursive.worldToCameraMatrix;Vector3 pp=mat.MultiplyPoint(new Vector3(0,0,-3.79f)),nn=mat.MultiplyVector(Vector3.forward).normalized;Vector4 plane=new Vector4(nn.x,nn.y,nn.z,-Vector3.Dot(pp,nn));recursive.projectionMatrix=recursive.CalculateObliqueMatrix(plane);recursive.Render();demo.portalMaterial.mainTexture=portalRT[i];}}
 static void Picture(string path,Camera which){if(job.topic=="portal")RenderPortal();which.Render();RenderTexture.active=which.targetTexture;image.ReadPixels(new Rect(0,0,W,H),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToJPG(93));RenderTexture.active=null;}
 public static void Run(){try{var args=Environment.GetCommandLineArgs();job=JsonUtility.FromJson<Job>(File.ReadAllText(args[Array.IndexOf(args,"-batchShortJob")+1]));Directory.CreateDirectory(job.output);Build();var report=new Report{topic=job.topic,driver=SystemInfo.graphicsDeviceName};
 if(job.mode.StartsWith("preview")){foreach(var s in job.sections.Where(x=>!x.StartsWith("game")).Distinct()){foreach(float e in new[]{.5f,2.0f,4.5f}){var r=State(0,s,e);Picture(Path.Combine(job.output,s+"-"+e.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+".jpg"),cam);if(job.topic=="superliminal")Picture(Path.Combine(job.output,s+"-player-"+e.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+".jpg"),player);report.records.Add(r);}}}
 else{var timeline=JsonUtility.FromJson<Timeline>(File.ReadAllText(job.timeline));Directory.CreateDirectory(Path.Combine(job.output,"frames"));Directory.CreateDirectory(Path.Combine(job.output,"player"));for(int f=0;f<timeline.frames;f++){var s=timeline.sections.First(x=>f>=x.startFrame&&f<x.endFrame);var r=State(f,s.id,(f-s.startFrame)/60f);if(!s.id.StartsWith("game"))Picture(Path.Combine(job.output,"frames",f.ToString("D5")+".jpg"),cam);if(!s.id.StartsWith("game")&&job.topic=="superliminal")Picture(Path.Combine(job.output,"player",f.ToString("D5")+".jpg"),player);
 if(s.id=="compare"&&job.topic=="ghost"){demo.section="off";demo.Apply();Picture(Path.Combine(job.output,"player",f.ToString("D5")+".jpg"),cam);demo.section=s.id;demo.Apply();}report.records.Add(r);if(f%300==0)Debug.Log("BATCH_FRAME "+job.topic+" "+f+"/"+timeline.frames);}}
 report.frames=report.records.Count;report.scenes=Directory.GetFiles(Root+"/Scenes/"+job.topic,"*.unity");File.WriteAllText(Path.Combine(job.output,"readback.json"),JsonUtility.ToJson(report,true));File.WriteAllText(Path.Combine(job.output,"success.json"),"{\"frames\":"+report.frames+",\"width\":1080,\"height\":1080}");EditorApplication.Exit(0);
 }catch(Exception ex){Debug.LogException(ex);EditorApplication.Exit(1);}}
 }
